// Multi-wallet registry.
//
// Desktop / any browser with extensions: EIP-6963 (`eip6963:announceProvider`)
// lets every installed wallet extension announce itself with its own name,
// icon, and isolated EIP-1193 provider -- this is what makes "show every
// wallet's real icon and name" possible instead of guessing off window.ethereum.
//
// Mobile browser with no extension: there is no window.ethereum to discover,
// so we offer deep links straight into each wallet app's own in-app browser
// (verified against each wallet's own docs) plus, optionally, WalletConnect.
import { WALLETCONNECT_PROJECT_ID, APP_METADATA } from "./config.js";

const injected = new Map(); // rdns -> { info: {uuid,name,icon,rdns}, provider }
let listenerBound = false;

function isMobile() {
  return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent || "");
}
export { isMobile };

// Starts listening for EIP-6963 announcements. Safe to call multiple times.
export function startWalletDiscovery() {
  if (listenerBound) {
    // Wallets that finished initializing after our first request can still
    // announce late; ask again in case we missed any.
    window.dispatchEvent(new Event("eip6963:requestProvider"));
    return;
  }
  listenerBound = true;
  window.addEventListener("eip6963:announceProvider", (event) => {
    const detail = event?.detail;
    if (!detail?.info?.rdns || !detail?.provider) return;
    injected.set(detail.info.rdns, { info: detail.info, provider: detail.provider });
    window.dispatchEvent(new CustomEvent("patchcourt:walletsChanged"));
  });
  window.dispatchEvent(new Event("eip6963:requestProvider"));
}

// Every EIP-6963-announced wallet, each with its own icon/name/provider.
export function getInjectedWallets() {
  return Array.from(injected.values());
}

export function getInjectedByRdns(rdns) {
  return injected.get(rdns) || null;
}

const GENERIC_WALLET_ICON =
  "data:image/svg+xml;base64," +
  btoa(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#00c8ff" stroke-width="1.8"><path d="M3 7a2 2 0 0 1 2-2h13a1 1 0 0 1 1 1v3H5a2 2 0 0 1-2-2Z"/><path d="M3 9v9a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7a1 1 0 0 0-1-1H8"/><circle cx="16.6" cy="14.5" r="1.15" fill="#00c8ff" stroke="none"/></svg>`
  );

// Fallback for a legacy wallet that injects window.ethereum but hasn't
// adopted EIP-6963 yet. Rare in 2026, but still exists on some extensions.
export function getLegacyInjectedWallet() {
  if (typeof window === "undefined" || !window.ethereum) return null;
  const alreadyAnnounced = Array.from(injected.values()).some((w) => w.provider === window.ethereum);
  if (alreadyAnnounced) return null;
  const name = window.ethereum.isMetaMask
    ? "MetaMask"
    : window.ethereum.isRabby
      ? "Rabby"
      : window.ethereum.isCoinbaseWallet
        ? "Coinbase Wallet"
        : "Injected wallet";
  return { info: { rdns: "legacy-injected", name, icon: GENERIC_WALLET_ICON, uuid: "legacy" }, provider: window.ethereum };
}

// Small self-contained icons (no external hotlinks that can 404/CORS-fail).
// Each is a simple recognizable mark in that wallet's brand color, not a
// traced logo -- enough to tell the options apart at a glance in the list.
function markIcon(fill, glyphPath) {
  return (
    "data:image/svg+xml;base64," +
    btoa(
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="${fill}"/><path d="${glyphPath}" fill="#0b0f14"/></svg>`
    )
  );
}

