// True if `name` (from an EIP-6963 announcement) is the same brand as a
// catalog entry, so we never show both an "installed" and a "not installed"
// row for the same wallet.
export function catalogMatches(catalogEntry, injectedName) {
  if (!injectedName) return false;
  const a = catalogEntry.name.toLowerCase().replace(/\s|wallet/g, "");
  const b = injectedName.toLowerCase().replace(/\s|wallet/g, "");
  return a === b || a.includes(b) || b.includes(a);
}

export function currentPageUrl() {
  return `${location.origin}${location.pathname}${location.search}`;
}

// --- WalletConnect (optional, only if a project ID is configured) ---------
let wcProviderPromise = null;

export function isWalletConnectConfigured() {
  return Boolean(WALLETCONNECT_PROJECT_ID);
}

// Loaded lazily so a project with no WalletConnect project ID never pays for
// (or risks failing on) the extra network fetch.
export async function getWalletConnectProvider() {
  if (!WALLETCONNECT_PROJECT_ID) throw new Error("WalletConnect is not configured for this deployment (missing project ID).");
  if (wcProviderPromise) return wcProviderPromise;
  wcProviderPromise = (async () => {
    const { EthereumProvider } = await import("https://esm.sh/@walletconnect/ethereum-provider@2?bundle");
    const provider = await EthereumProvider.init({
      projectId: WALLETCONNECT_PROJECT_ID,
      optionalChains: [1, APP_METADATA.studioChainId],
      showQrModal: true,
      metadata: APP_METADATA.wc,
    });
    return provider;
  })();
  try {
    return await wcProviderPromise;
  } catch (error) {
    wcProviderPromise = null;
    throw error;
  }
}
